{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "In mice, a benzamide bearing a 1-benzyl-4-piperidinyl amide substituent showed significant and lasting high brain uptake, directly supporting meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In ICR mice, compound 24r given intragastrically was detected in brain with brain/plasma ratios of 4.2–8.5 at all timepoints, indicating excellent BBB penetration after oral systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In healthy humans, roxatidine was detected in CSF only in traces after oral dosing, with CSF:plasma ratios up to 0.089, arguing against meaningful CNS access for that particular analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple direct in-vivo studies in mice, rats, and monkeys show high brain uptake and brain/plasma ratios >1 for benzamide/piperidine analogs, supporting meaningful CNS access. The negative human CSF result for roxatidine and low-uptake benzimidazole records come from less similar chemotypes and do not override the consistent positive series.",
  "evidence_gaps": [
    "No direct query-specific PK data; all evidence is from analogs with Morgan similarity around 0.28–0.34.",
    "Negative records are from different chemotypes (roxatidine, benzimidazoles) and may not transfer to the benzamide/piperidine series.",
    "Several positive records are qualitative imaging or brain-uptake measurements rather than quantitative unbound brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

